mapper.sql:
WHERE 1 = 1
AND (u.username LIKE CONCAT('%', #{keyword}, '%') OR u.full_name LIKE CONCAT('%', #{keyword}, '%') OR l.action LIKE CONCAT('%', #{keyword}, '%') OR l.path LIKE CONCAT('%', #{keyword}, '%') OR l.target LIKE CONCAT('%', #{keyword}, '%') OR l.ip LIKE CONCAT('%', #{keyword}, '%'))
AND l.action = #{action} AND l.result = #{result}
